<?php
require_once __DIR__ . '/../includes/auth.php';require_reviewer();$rid=(int)$_SESSION['reviewer_id'];$status=$_GET['status']??'';
$sql='SELECT ra.*,a.abs_id,a.topic AS abstract_title,a.presentation,a.mode_presentation1,a.mode_presentation2,a.type_of_eposter,ar.decision,ar.is_final,ar.is_locked FROM review_assignments ra JOIN abstract a ON a.id=ra.abstract_id LEFT JOIN abstract_reviews ar ON ar.assignment_id=ra.id WHERE ra.reviewer_id=? AND ra.is_active=1';$types='i';$params=[$rid];if(in_array($status,['pending','under_review','accepted','rejected','resubmit','cannot_review'],true)){$sql.=' AND ra.status=?';$types.='s';$params[]=$status;}$sql.=' ORDER BY (ra.review_deadline IS NULL),ra.review_deadline,a.id';$st=db()->prepare($sql);$st->bind_param($types,...$params);$st->execute();$rows=$st->get_result()->fetch_all(MYSQLI_ASSOC);
$pageTitle='My Abstracts';require __DIR__ . '/../includes/header.php';
?>
<div class="d-flex justify-content-between align-items-center mb-3"><h2>My Assigned Abstracts</h2><form><select class="form-select" name="status" onchange="this.form.submit()"><option value="">All Status</option><?php foreach(['pending','under_review','accepted','rejected','resubmit','cannot_review'] as $s):?><option value="<?= $s ?>" <?= $status===$s?'selected':'' ?>><?= e(decision_label($s)) ?></option><?php endforeach;?></select></form></div><div class="card"><div class="card-body"><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Abstract ID</th><th>Title</th><th>Presentation</th><th>Mode 1</th><th>Type</th><th>Deadline</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= e($r['abs_id']) ?></td><td style="min-width:320px"><?= e($r['abstract_title']) ?></td><td><?= e($r['presentation']) ?></td><td><?= e($r['mode_presentation1']) ?></td><td><?= e($r['type_of_eposter']) ?></td><td><?= $r['review_deadline']?e(date('d M Y, h:i A',strtotime($r['review_deadline']))):'—' ?></td><td><?= status_badge($r['status']) ?></td><td><a class="btn btn-sm btn-brand" href="abstract-view.php?id=<?= (int)$r['abstract_id'] ?>">Review</a></td></tr><?php endforeach;?></tbody></table></div></div></div>
